Item.method_code:
/*
    親IDとrelationshipを渡して、子のどドキュメントのコンフィグIDを返す
    returnItemの子のconfig_id として返却
*/
Innovator inn = this.getInnovator();

//権限付与用
Aras.Server.Security.Identity adminIdentity = Aras.Server.Security.Identity.GetByName("Administrators");
    	
// 引数取得 
string relitemtypeName = this.getProperty("relitemtypeName");
string sourceID = this.getProperty("sourceID");

//リレーションのパーミッションID、related_id取得
Item reltype = inn.newItem(relitemtypeName, "get");
reltype.setAttribute( "select", "config_id, related_id, id, h4_parent_order_no" );
reltype.setProperty("source_id", sourceID); 
using (CCO.Permissions.GrantIdentity(adminIdentity))
{
    reltype = reltype.apply();
    if(reltype.isError() && reltype.getItemCount() == -1)
    {
        return inn.newError(CCO.ErrorLookup.Lookup("h4_S_E_0002"));   
    }
}

var resultItem = inn.newItem("Result","get");
for (int j = 0; j < reltype.getItemCount(); j++)
{
	Item docrec = reltype.getItemByIndex(j);
	string relatedid = docrec.getProperty("related_id", "");
	if(relatedid != "")
	{
    	Item selDoc = inn.newItem("Document","get");
        selDoc.setAttribute( "select", "config_id" );
    	selDoc.setProperty("id", relatedid);
        using (CCO.Permissions.GrantIdentity(adminIdentity))
        {
            selDoc = selDoc.apply();
            if(selDoc.isError())
            {
                return inn.newError(CCO.ErrorLookup.Lookup("h4_S_E_0002"));   
            }
        }
        
        Item tmpItem = inn.newItem("Item", "get");
        tmpItem.setProperty("config_id", selDoc.getProperty("config_id",""));
        tmpItem.setProperty("parent_order_no", docrec.getProperty("h4_parent_order_no",""));
        resultItem.addRelationship(tmpItem);  // 子として追加
	}
}

return resultItem;
